package org.marketreview.nativeapp;
import android.content.Context;
import android.os.Handler;
import android.os.Looper;
import android.view.View;
import android.widget.*;
import org.json.*;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
public final class AiSettingsChecks {
 private static int checks;
 private static void ok(boolean value)throws Exception{if(!value)throw new Exception("AI 设置断言失败");checks++;}
 private interface Work{void run()throws Exception;}
 private static void rejects(Work work)throws Exception{boolean failed=false;try{work.run();}catch(Exception e){failed=true;}ok(failed);}
 public static void main(String[] args)throws Exception{model();System.out.println("AiSettings model PASS "+checks);}
 public static void model()throws Exception{JSONObject p=AiSettingsModel.preferences(new JSONObject());ok(p.getInt("timeoutMs")==120000);for(String e:new String[]{"http://example.com/v1","https://u:sk-fixture-secret@example.com/v1","https://127.0.0.1/v1","https://localhost/v1","https://a.local/v1","https://example.com/v1?key=x","https://example.com/v1#x","https://example.com/%73k-token","https://[::1]/v1"})rejects(()->AiSettingsModel.preferences(new JSONObject().put("endpoint",e)));rejects(()->AiSettingsModel.preferences(new JSONObject().put("model","sk-fixture-secret")));rejects(()->AiSettingsModel.preferences(new JSONObject().put("timeoutMs",1000.1)));rejects(()->AiSettingsModel.preferences(new JSONObject().put("endpoint",5)));rejects(()->AiSettingsModel.preferences(new JSONObject().put("sendTemperature",true)));JSONObject safe=AiSettingsModel.parse("{\"model\":\"model-a\",\"apiKey\":\"sk-fixture-secret\",\"headers\":{\"Authorization\":\"Bearer sk-fixture-secret\"},\"capabilities\":[{\"id\":\"openai-direct\",\"status\":\"available\",\"note\":\"sk-fixture-secret\"}]}".getBytes(StandardCharsets.UTF_8));ok(!safe.toString().contains("sk-fixture-secret"));rejects(()->AiSettingsModel.parse(new JSONObject().put("capabilities",new JSONArray().put(new JSONObject().put("id","model-sk-fixture-secret").put("status","available"))).toString().getBytes(StandardCharsets.UTF_8)));ok(safe.getJSONArray("capabilities").getJSONObject(0).getString("status").equals("reported-unverified"));AiSettingsCapabilities.validateReports(safe.getJSONArray("capabilities"));JSONObject config=AiSettingsModel.preferences(new JSONObject().put("provider","openai").put("baseUrl","https://api.openai.com/v1").put("model","test-model").put("maxTokens",512));ok(config.getString("endpoint").equals("https://api.openai.com/v1/chat/completions"));ok(!AiSettingsModel.status(config).getBoolean("credentialConfigured"));ok(AiSettingsModel.status(config).getString("connectivity").equals("not-tested"));}
 public static void store(Context context)throws Exception{File file=new File(context.getCacheDir(),"ai-settings-"+System.nanoTime()+".sqlite");AiSettingsStore store=new AiSettingsStore(file);JSONObject first=store.save(AiSettingsModel.preferences(new JSONObject().put("model","model-a")),new JSONArray(),0);ok(AiSettingsModel.equal(first,store.read()));rejects(()->store.save(AiSettingsModel.preferences(new JSONObject().put("model","model-b")),new JSONArray(),0));ok(AiSettingsModel.equal(first,store.read()));JSONArray caps=AiSettingsCapabilities.reported(new JSONArray().put(new JSONObject().put("id","model-a").put("status","available")),"import");caps.getJSONObject(0).put("source","sk-fixture-secret");rejects(()->store.save(first.getJSONObject("preferences"),caps,1));file.delete();}
 private static void mainThread(Work work)throws Exception{if(Looper.myLooper()==Looper.getMainLooper()){work.run();return;}CountDownLatch done=new CountDownLatch(1);Exception[] errors={null};new Handler(Looper.getMainLooper()).post(()->{try{work.run();}catch(Exception e){errors[0]=e;}finally{done.countDown();}});ok(done.await(20,TimeUnit.SECONDS));if(errors[0]!=null)throw errors[0];}
 public static void foreignStore(Context context)throws Exception{
  File file=new File(context.getCacheDir(),"ai-foreign-"+System.nanoTime()+".sqlite");
  try(android.database.sqlite.SQLiteDatabase db=android.database.sqlite.SQLiteDatabase.openOrCreateDatabase(file,null)){db.execSQL("CREATE TABLE preserved(value TEXT)");db.execSQL("INSERT INTO preserved VALUES('fixture-kept')");}
  rejects(()->new AiSettingsStore(file).save(AiSettingsModel.preferences(new JSONObject()),new JSONArray(),0));
  try(android.database.sqlite.SQLiteDatabase db=android.database.sqlite.SQLiteDatabase.openDatabase(file.toString(),null,android.database.sqlite.SQLiteDatabase.OPEN_READONLY);android.database.Cursor c=db.rawQuery("SELECT value FROM preserved",null)){ok(c.moveToFirst()&&c.getString(0).equals("fixture-kept"));}
 }
 public static void ui(Context context)throws Exception{mainThread(()->{File file=new File(context.getCacheDir(),"ai-ui-"+System.nanoTime()+".sqlite");AiSettingsScreen screen=new AiSettingsScreen(context,file,()->{});EditText model=screen.findViewWithTag("aiModel");Button save=screen.findViewWithTag("aiSave"),cancel=screen.findViewWithTag("aiCancel");model.setText("model-a");save.performClick();ok(screen.savedConfig().getString("model").equals("model-a"));model.setText("model-b");cancel.performClick();ok(model.getText().toString().equals("model-a"));model.setText("sk-fixture-secret");JSONObject marker=screen.saveState();ok(!marker.toString().contains("sk-fixture-secret"));screen.restoreState(marker);ok(model.getText().toString().equals("model-a"));screen.importArchive("{\"model\":\"model-import\",\"apiKey\":\"sk-fixture-secret\"}".getBytes(StandardCharsets.UTF_8));Button apply=screen.findViewWithTag("aiApply");ok(apply.isEnabled());apply.performClick();ok(screen.savedConfig().getString("model").equals("model-import"));AiSettingsScreen reopened=new AiSettingsScreen(context,file,()->{});ok(AiSettingsModel.equal(screen.savedConfig(),reopened.savedConfig()));ok(!new String(reopened.exportArchive(),StandardCharsets.UTF_8).contains("sk-fixture-secret"));ok(!reopened.<Button>findViewWithTag("aiHandoff").isEnabled());screen.close();reopened.close();file.delete();new File(file+".ui.json").delete();});}
 public static void geometry(Context context)throws Exception{mainThread(()->{File file=new File(context.getCacheDir(),"ai-layout-"+System.nanoTime()+".sqlite");AiSettingsScreen screen=new AiSettingsScreen(context,file,()->{});float density=context.getResources().getDisplayMetrics().density;for(int[] size:new int[][]{{420,640},{840,190}}){screen.measure(View.MeasureSpec.makeMeasureSpec(Math.round(size[0]*density),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(Math.round(size[1]*density),View.MeasureSpec.EXACTLY));screen.layout(0,0,screen.getMeasuredWidth(),screen.getMeasuredHeight());ok(screen.getMeasuredHeight()>0);ok(((ScrollView)screen.getChildAt(1)).getMeasuredHeight()>Math.round(60*density));Button save=screen.findViewWithTag("aiSave");ok(save.getMeasuredHeight()>=Math.round(48*density));for(boolean dark:new boolean[]{false,true}){screen.setDarkTheme(dark);ok(save.getCurrentTextColor()!=save.getBackgroundTintList().getDefaultColor());}}screen.close();file.delete();});}
}
